_raw=zlib.decompress(base64.b85decode(FROZEN_50M_B85))
if hashlib.sha256(_raw).hexdigest()!=FROZEN_50M_SHA:raise RuntimeError('封存运行时hash不符')
_tree=ast.parse(_raw.decode('utf-8-sig'))
_tree.body=[n for n in _tree.body if not (isinstance(n,ast.If) and isinstance(n.test,ast.Compare) and isinstance(n.test.left,ast.Name) and n.test.left.id=='__name__')]
