VERSION='UAM_CREDIT_HORIZON_18H_20261102_V1'
ATTR_ROOT='uam_credit_horizon_32run_18h_v1'
ATTR_STEPS=STEPS=FULL_ACTUAL_STEPS=2_396_160
ATTR_PLANNED=32*ATTR_STEPS
ATTR_CAP=HARD_CAP=80_000_000
GAP_VERSION=VERSION
_original_setup=gap_setup
_original_manifest=gap_update_manifest


def credit_setup(task,root,phase):
    # 仅折扣因子是预注册实验因素；所有组逐分钟奖励、物理、训练长度一致。
    SOURCE_PPO['gamma']=float(task['gamma'])
    return _original_setup(task,root,phase)


gap_setup=attr_setup=credit_setup


def credit_manifest(folder,task):
    _original_manifest(folder,task)
    p=Path(folder)/'MODEL_MANIFEST.json';m=read_json(p,{})
    m.update(version=VERSION,experimental_gamma=task['gamma'],ppo=dict(SOURCE_PPO),
        reward_normalization_gamma=.99,normalization_scope='归一化统计沿用源.99，所有实验臂一致；本轮因素只改变PPO折扣',
        gamma_warning='本轮显式比较.99和1.0；没有改逐分钟PT_POST奖励；500分钟训练截断不等于全程ATT',
        main_question='新信息用普通网络已经给足后，折扣范围是否影响同一有限预算下的服务选择',
        information='所有组相同的合法时间与四座余数描述符；无辅助损失、无未来真值',
        no_novelty_claim='这是问题归因和强普通基线校准，不是新WM或MARL方法',
        entrypoint_sha256=digest(SCRIPT),frozen_50m_sha256=FROZEN_50M_SHA)
    save_json(p,m)


attr_update_manifest=credit_manifest


def credit_tasks():
    rng=random.Random(20261102);tasks=[]
    # 联合是首要问题，先完成它的四个种子；随后独立验证单侧是否同样受影响。
    for control in ('J3','LQ'):
        for seed in (1801,1802,1803,1804):
            cells=[(net,gamma) for net in ('LSTM','TRANSFORMER') for gamma in (.99,1.)]
            rng.shuffle(cells)
            for net,gamma in cells:
                arm=('L' if net=='LSTM' else 'T')+('_G099' if gamma==.99 else '_G100')
                tasks.append(dict(id=f'CORE__E1__K3__{control}__{arm}__s{seed}',stage='CORE_J' if control=='J3' else 'CONFIRM_SINGLE',
                    environment='E1',k=3,fleet=12,seed=seed,arm=arm,control=control,
                    reward_mode='PT_POST',time_mode='RAW',variant='M0_BASE',
                    method=('J3' if control=='J3' else 'SINGLE')+'__M0_BASE',
                    timing=True,batch=True,network=net,gamma=gamma,run_order=len(tasks)+1))
    assert len(tasks)==32 and ATTR_PLANNED==76_677_120
    return tasks


def aggregate(root,tasks):
    rows=[];status=[];initial={}
    for t in tasks:
        d=root/'cells'/t['id'];tr=read_json(d/'TRAIN_END.json');r=read_json(d/'RESULT.json')
        status.append(dict(**t,trained=bool(tr),evaluated=bool(r),steps=int(tr['steps']) if tr else int(read_json(d/'LIVE.json',{}).get('steps',0)),
                           failed=bool(list(d.glob('FAILED_*.json')))))
        ini=read_json(d/'INITIAL_POLICY_SHA.json',{})
        if ini:initial.setdefault((t['seed'],t['control'],t['network']),set()).add(ini['sha256'])
        if r:
            m=r['main_late_confirmation'];f=r['final_confirmation']
            rows.append(dict(**t,late_rpt=m['rpt'],late_completion=m['completion'],late_full_fraction=m['full_episode_fraction'],
                late_att=m['full_att'],final_rpt=f['rpt'],final_completion=f['completion'],
                rollback=r['original_curve_stability']['best_to_late_ratio'],eval_seconds=r['eval_seconds']))
    if any(len(v)>1 for v in initial.values()):raise RuntimeError('同种子同网络的两个折扣组初始参数不一致')
    by={(r['seed'],r['control'],r['network'],r['gamma']):r for r in rows};pairs=[]
    for seed,control,network in sorted({(r['seed'],r['control'],r['network']) for r in rows}):
        low,high=by.get((seed,control,network,.99)),by.get((seed,control,network,1.))
        if low and high:pairs.append(dict(seed=seed,control=control,network=network,contrast='gamma1减gamma099',
            delta_rpt=high['late_rpt']-low['late_rpt'],delta_completion=high['late_completion']-low['late_completion']))
    measured,upper=budget_account(root)
    p=dict(total=len(tasks),trained=sum(x['trained'] for x in status),evaluated=sum(x['evaluated'] for x in status),
           failed=sum(x['failed'] for x in status),completed_training_transitions=sum(x['steps'] for x in status if x['trained']),
           measured_training_work=measured,interrupted_unlogged_upper_bound=upper,
           planned_actual_budget=ATTR_PLANNED,budget_cap=ATTR_CAP,time=now())
    save_csv(root/'MODEL_RESULTS.csv',rows);save_csv(root/'RUN_STATUS.csv',status);save_csv(root/'PAIRED_EFFECTS.csv',pairs);save_json(root/'progress.json',p)
    return p


def take_lock(root):
    handle=(root/'PARENT_LOCK').open('a+b')
    if os.name=='nt':
        import msvcrt
        handle.seek(0)
        if not handle.read(1):handle.write(b'0');handle.flush()
        handle.seek(0);msvcrt.locking(handle.fileno(),msvcrt.LK_NBLCK,1)
    else:
        import fcntl
        fcntl.flock(handle.fileno(),fcntl.LOCK_EX|fcntl.LOCK_NB)
    return handle


def main():
    ap=argparse.ArgumentParser(description=__doc__)
    ap.add_argument('--resume',action='store_true');ap.add_argument('--retry-failed',action='store_true')
    ap.add_argument('--device',default='cuda');ap.add_argument('--eval-device',default='cpu')
    ap.add_argument('--wall-hours',type=float,default=18.);ap.add_argument('--min-free-gib',type=float,default=15.)
    ap.add_argument('--phase',choices=('all','train','eval','pack'),default='all')
    ap.add_argument('--plan',action='store_true');ap.add_argument('--root')
    ap.add_argument('--worker',choices=('train','eval','rules'));ap.add_argument('--task')
    args=ap.parse_args();tasks=credit_tasks()
    if args.plan:
        print(json.dumps(dict(version=VERSION,tasks=tasks,actual_steps=ATTR_PLANNED,
            wall_hours=args.wall_hours,note='18小时是占机预算估算，不保证共享服务器按时跑满32格'),ensure_ascii=False,indent=2));return
    project=Path(__file__).resolve().parent
    root=Path(args.root).resolve() if args.root else project/'serial_runs'/ATTR_ROOT
    if root.name!=ATTR_ROOT or root.is_symlink() or not root.is_relative_to(project/'serial_runs'):raise RuntimeError('输出只能在本项目新实验目录')
    if args.worker:
        record=read_json(args.task);t,config=record['task'],record['config']
        SOURCE_PPO['gamma']=float(t['gamma'])
        os.environ['UAM_ATTR_TRACE_SHA']=digest(config['trace'])
        dict(train=attr_train,eval=gap_eval,rules=gap_rules)[args.worker](t,root,config);return
    if args.wall_hours<=0 or args.wall_hours>18:raise RuntimeError('单会话预算必须在0到18小时之间')
    root.mkdir(parents=True,exist_ok=True);lock=take_lock(root);started=time.monotonic()
    old=read_json(root/'SUITE_PLAN.json')
    if old and (old['script_sha256']!=digest(SCRIPT) or old['tasks']!=tasks):raise RuntimeError('代码或任务合同改变，不能混入旧结果')
    if old and not args.resume and args.phase!='pack':raise RuntimeError('已有结果；请使用--resume')
    if not old and (root/'cells').exists() and any((root/'cells').iterdir()):raise RuntimeError('已有数据缺清单，保留待查')
    native=materialize_source(root);bank=gap_bank(root,native)
    config=dict(version=VERSION,device=args.device,eval_device=args.eval_device,trace=str(native/'train_data/passengers_300.csv'),bank=bank,
        train_horizon=500,eval_horizon=600,actual_steps=ATTR_STEPS,requested_steps=ATTR_STEPS,
        resume=args.resume,retry_failed=args.retry_failed,timeout_hours=2.)
    if old:
        for key in ('device','eval_device','trace','bank','train_horizon','eval_horizon','actual_steps'):
            if old['config'][key]!=config[key]:raise RuntimeError('续跑合同改变：'+key)
    else:
        save_json(root/'SUITE_PLAN.json',dict(version=VERSION,script_sha256=digest(SCRIPT),frozen_50m_sha256=FROZEN_50M_SHA,
            config=config,tasks=tasks,ppo_common={k:v for k,v in SOURCE_PPO.items() if k!='gamma'},gamma_levels=[.99,1.],
            planned_actual_budget=ATTR_PLANNED,budget_cap=ATTR_CAP,
            primary='K3每控制×网络，4独立种子配对比较gamma；所有组相同信息，不按Best挑冠军',
            validation='复用4301至4304已看过的验证顺序，绝不冒称全新独立需求测试',
            wall_estimate='历史整体1346FPS；保守1200FPS时本计划约17.75小时；本机实际负载会变化'))
    save_json(root/'TASK_REGISTRY.json',tasks)
    status=read_json(root/'END.json',{}).get('status','PARTIAL') if args.phase=='pack' else 'PARTIAL';reason=None
    try:
        if args.phase=='pack':
            if status=='COMPLETE':gap_pack_models(root,tasks)
            attr_pack(root);return
        for i,t in enumerate(tasks,1):
            if (root/'STOP_REQUESTED').exists():reason='用户请求停止';break
            elapsed=time.monotonic()-started
            # 不在剩余时间不足约40分钟时再开一格；这是保守准入，不擅自改变训练长度。
            if elapsed+2400>args.wall_hours*3600:reason='本会话时间预留不足，保留完整格并可续跑';break
            if args.phase in ('all','train') and not (root/'cells'/t['id']/'TRAIN_END.json').exists():
                gap_resource_check(root,args.device,args.min_free_gib)
                print(f'[训练 {i}/{len(tasks)}]',t['id'],'gamma=',t['gamma'],flush=True)
                remaining=args.wall_hours*3600-(time.monotonic()-started)-90
                attr_launch('train',t,root,dict(config,timeout_hours=min(2.,max(.01,remaining/3600))))
            if args.phase in ('all','eval') and (root/'cells'/t['id']/'TRAIN_END.json').exists():
                remaining=args.wall_hours*3600-(time.monotonic()-started)-90
                if remaining<30:reason='本会话剩余时间不足，评估保留到续跑';break
                attr_launch('eval',t,root,dict(config,timeout_hours=min(2.,remaining/3600)))
            aggregate(root,tasks)
        p=aggregate(root,tasks)
        status='COMPLETE' if p['evaluated']==len(tasks) and not p['failed'] else 'PARTIAL'
        save_json(root/'END.json',dict(status=status,progress=p,time=now(),wall_seconds=time.monotonic()-started,reason=reason,
            note='未完成格原样保留；不因18小时到点而把PARTIAL写成COMPLETE'))
        if status=='COMPLETE':gap_pack_models(root,tasks)
        attr_pack(root)
    except KeyboardInterrupt:
        aggregate(root,tasks);save_json(root/'INTERRUPTED.json',dict(time=now(),note='同代码--resume；不删除已完成格'));raise SystemExit(130)
    finally:
        save_json(root/'RUNNING.json',dict(phase='complete' if status=='COMPLETE' else 'idle_partial',task=None,pid=None,time=now()))
        lock.close()


if __name__=='__main__':main()
